import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "<p>JPGとPNGは、Webで最も古い2つの画像形式で、正反対の問題を解決します。JPGは写真を小さくし、PNGはグラフィックを完璧に保ち、透明にもできます。</p>\n<p>両者の最も誤解されやすい違いが、透過です。JPGは透過をまったく保存できず、PNGは保存できます。ところがJPGをPNGに変換しても、魔法のように透過は生まれません。</p>\n<p>この記事では、2つの形式を正直に比較します。扱う画像ごとに、正しい形式を選べるようになります。</p>\n<h2 id=\"jpg-at-a-glance\">JPGの概要</h2>\n<p>JPGは、写真向けに設計された非可逆形式です。目がほとんど気付かない細部を捨てるので、写真ファイルは可逆形式より大幅に小さくなります。</p>\n<p>典型的なスマホ写真は、JPGで3MB、PNGで15MBです。この差が、すべてのカメラ、スマホ、Webサイトが写真にJPGを使う理由です。</p>\n<p>JPGは8ビットカラーのみで、透過には対応しません。すべての画素に色があり、透けて見えるJPGの画素は存在しません。</p>\n<p>この形式は万能です。過去30年間に作られたすべての端末、ブラウザ、プリンター、アップロードフォームが、追加のソフトなしにJPGを開けます。</p>\n<h2 id=\"png-at-a-glance\">PNGの概要</h2>\n<p>PNGは、グラフィック向けに設計された可逆形式です。すべての画素を正確に保存するので、シャープな輪郭、ベタ塗りの色、文字が完璧にくっきり残ります。</p>\n<p>PNGは、アルファチャンネルで透過に対応します。各画素は、完全に透明、完全に不透明、部分的に透明のいずれかになれます。柔らかい輪郭や影も可能です。</p>\n<p>代償はファイルサイズです。詳細な写真をPNGで保存すると、同じ写真のJPGの数倍大きくなります。可逆保存では、質感を捨てられないからです。</p>\n<p>PNGも万能ですが、写真では効率が悪くなります。すべてのブラウザ、編集ソフト、Officeアプリが、問題なくPNGファイルを開けます。</p>\n<h2 id=\"what-transparency-is\">透過とは何か</h2>\n<p>透過とは、画像の一部が背景を透かして見せることです。透明な背景のロゴは、白いページ、色付きのWebサイト、暗いスライドのどこに置いても、周りに白い四角がなく、きれいに収まります。</p>\n<p>ファイルの中では、透過はアルファチャンネルとして保存されます。各画素がどれだけ透けるかを示す追加のデータ層です。値が0なら見えず、255なら完全に不透明です。</p>\n<p>部分的な透過は、柔らかい輪郭を可能にします。ドロップシャドウは、不透明から透明へ少しずつ消えていき、どの背景でも自然に見えます。</p>\n<p>JPGには、アルファチャンネルがまったくありません。これは設定ではなく、構造的な事実です。世界中のどのJPGファイルにも、透過はありません。</p>\n<h2 id=\"when-transparency-matters\">透過が本当に重要なとき</h2>\n<p>ロゴが典型的な例です。企業のロゴは、白いページ、色付きのWebサイト、暗いスライドに置かれなければならず、透過だけが1つのファイルをどこでも機能させます。</p>\n<p>アイコンやステッカーも透過が必要です。白い四角に囲まれたアプリのアイコンは壊れて見えますが、透明なアイコンはどの画面にもなじみます。</p>\n<p>ネットショップの商品の切り抜きも、透過に依存します。背景を取り除いた商品写真は、ショップの背景色が何色でも、きれいに収まります。</p>\n<p>重ね合わせや透かしは、部分的な透過を使います。写真の上に置いた半透明のロゴは、写真を見せながら、ブランドも見える状態に保ちます。</p>\n<h2 id=\"when-it-does-not-matter\">透過が重要でないとき</h2>\n<p>写真に透過は決して必要ありません。写真は、透ける部分のない画素の長方形です。JPGはそれを完璧に扱います。</p>\n<p>書類やスキャンも透過は不要です。スキャンしたページは、完全な長方形です。白い背景は正解であり、解決すべき問題ではありません。</p>\n<p>SNSの投稿も、透過はめったに必要ありません。InstagramやFacebookに投稿する写真は、枠いっぱいに広がります。透過があっても見えません。</p>\n<p>画像に透ける部分がない場合、透過は関係ありません。ファイルサイズとシャープさで形式を選んでください。</p>\n<h2 id=\"converting-cannot-add-transparency\">変換では透過を作れない理由</h2>\n<p>JPGには透明な画素がないので、PNGに変換しても、PNGに透明な画素は生まれません。白い背景は、白い画素として保存され、透けるものではありません。</p>\n<p>透過を得る唯一の方法は、背景を正しく取り除くことです。背景除去ツールを使えば、AIが被写体を切り抜き、透明なPNGとして保存できます。</p>\n<p>編集ソフトで白い画素を削除して、透過と呼ぼうとする人もいます。これはシンプルな画像にしか使えず、詳細なものでは輪郭がギザギザになります。</p>\n<p>きれいな結果を得るには、すでに透過のあるPNGから始めるか、適切なツールで背景を取り除いてください。変換だけでは、透過は決して生まれません。</p>\n<h2 id=\"file-size-compared\">ファイルサイズを正直に比較する</h2>\n<p>写真では、JPGが大きな差で勝ちます。3MBのJPG写真は、12MBから18MBのPNGになります。目に見える改善がないのに、余分なバイトがかかります。</p>\n<p>シンプルなグラフィックでは、PNGが勝ちます。ベタ塗りの色と大きな空きのあるロゴは、PNGとしてよく圧縮でき、同じ画像のJPGより小さいこともあります。</p>\n<p>文字入りのスクリーンショットでは、両者は近くなります。PNGは大きいですが、文字はシャープに残ります。JPGは文字をにじませるので、余分なサイズには本当の品質の価値があります。</p>\n<p>Webでは、WebPが両方を上回ります。JPGのようなサイズで、PNGのような透過を提供します。送り先が対応している場合は、選ぶべき形式です。</p>\n<h2 id=\"text-and-sharpness\">文字のシャープさと線画</h2>\n<p>PNGは、すべての画素を正確に保存するので、文字をくっきり保ちます。スクリーンショット、図、グラフは、どの拡大率でもPNGできれいに見えます。</p>\n<p>JPGは、圧縮で画素をブロックにまとめるので、文字をにじませます。小さな文字はハローが出て輪郭が柔らかくなり、読みにくくなります。</p>\n<p>グラフや技術図面のような線画も、JPGでは同じように傷みます。細い線はぼやけますが、PNGはくっきり保ちます。</p>\n<p>文字や線が中身の画像には、PNGが正しい形式です。写真が中身の画像には、JPGが正しいです。</p>\n<h2 id=\"photos-compared\">写真：JPGが勝ち、PNGが負ける</h2>\n<p>写真には、何百万もの色がなめらかに溶け合っています。JPGはそのグラデーションを効率よく扱いますが、PNGはすべての微妙な変化を正確に保存しなければなりません。</p>\n<p>結果として、PNGの写真は数倍大きくなりますが、見た目は同じです。余分なバイトは、目に見えるものを何も買わず、読み込みの遅さは本当のコストです。</p>\n<p>例外は編集だけです。写真を何度も編集する予定があるなら、PNGはダメージの蓄積を止めます。JPGの繰り返し保存は、ダメージを加え続けます。</p>\n<p>ただし納品には、写真はJPGかWebPが常に優れています。PNGは、写真の作業用形式であり、納品用形式ではありません。</p>\n<h2 id=\"choosing-for-web\">Web用の選び方</h2>\n<p>Webサイトの写真には、JPGかWebPを使ってください。ファイルサイズが小さいので、ページの表示が速くなります。訪問者にも検索順位にも重要です。</p>\n<p>Webサイトのロゴやアイコンには、PNGかWebPを使ってください。ここでは透過が重要で、両方の形式がそれを保ちます。WebPのほうが、たいていファイルが小さくなります。</p>\n<p>Webサイトのスクリーンショットには、WebPかPNGを使ってください。文字は読みやすいままでなければならず、JPGは文字をにじませるので、可逆の選択肢には余分なバイトの価値があります。</p>\n<p>最近のWebサイトは、JPGやPNGのフォールバック付きでWebPを提供することが多いです。この組み合わせで、最近のブラウザには速い読み込みを、古いブラウザには互換性を提供します。</p>\n<h2 id=\"choosing-for-print\">印刷用の選び方</h2>\n<p>印刷する写真は、高画質のJPGで十分です。プリンターはJPGをよく扱い、大きな印刷作業でもファイルサイズは手頃です。</p>\n<p>文字のある印刷する書類は、PNGのほうがよいです。シャープな文字は紙の上でもきれいに印刷でき、JPGの文字は紙の上では柔らかく見えることがあります。</p>\n<p>印刷するロゴは、透過付きのPNGが標準です。ロゴは、印刷デザインのどの背景色の上でもきれいに収まります。</p>\n<p>ファイルを送る前に、印刷所に好みを尋ねてください。多くは両方の形式を受け付け、実用的な理由でどちらかを好む場合があります。</p>\n<h2 id=\"practical-rule\">覚えておくべき実用的なルール</h2>\n<p>すべての画像について、2つの質問をしてください。透過やシャープな文字はありますか。そして、写真ですか、グラフィックですか。</p>\n<p>透過やシャープな文字があれば、PNGです。それらの必要がない写真なら、JPGです。Web用のグラフィックは、両方を扱えるWebPになることが多いです。</p>\n<p>迷ったら、画像を見てください。人や場所の写真ならJPG、ロゴ、アイコン、スクリーンショットならPNGです。</p>\n<p>このシンプルなルールが、扱うほぼすべての画像をカバーします。例外はまれで、たいていは納品ではなく編集のワークフローに関わるものです。</p>\n<h2 id=\"logos-dark-backgrounds\">暗い背景のロゴ</h2>\n<p>暗い背景のロゴは透過が必要です。そうでないと、目に見える白い四角の中に収まります。透明な背景のPNGロゴは暗いデザインになじみますが、JPGのロゴはできません。</p>\n<p>暗い背景に表示されるロゴは、最初からPNGとしてデザインしてください。透明版は、暗い背景、明るい背景、色付きの背景のすべてで、1つのファイルで機能します。</p>\n<p>暗いテーマのWebサイトでは、実際の背景色の上でロゴをテストしてください。白の上では完璧に見えるロゴも、色が暗すぎれば黒の上では消えてしまいます。</p>\n<p>暗いテンプレートのスライドでも、同じルールが当てはまります。透明なPNGロゴは暗いスライドにきれいに収まりますが、JPGのロゴはデザインを壊す白い四角が必要です。</p>\n<p>ブランドが両方を使う場合は、明るい版と暗い版のロゴを残してください。暗い背景用の白いロゴと、明るい背景用の暗いロゴが、すべての状況をカバーします。</p>\n<h2 id=\"icons-apps-websites\">アプリやWebサイトのアイコン</h2>\n<p>アプリのアイコンは透過が必要です。壁紙のあるホーム画面に置かれるからです。透明な背景のPNGアイコンは、どの壁紙にもなじみます。JPGのアイコンは四角が見えます。</p>\n<p>Webサイトのファビコンは、たいていPNGかSVGです。32×32ピクセルのPNGファビコンは、ブラウザのタブでシャープに見え、ファイルサイズの小ささはほとんど関係ありません。</p>\n<p>画面内のアイコンは、サイズの一貫性が必要です。同じ画素寸法のPNGアイコン一式は、均一に見えます。サイズが混ざると雑に見えます。</p>\n<p>最近のWebサイトでは、WebPのアイコンがPNGのアイコンより小さく、透過も同じです。PNGのアイコンをWebPに変換してライブサイトに使い、PNGのマスターは編集用に残してください。</p>\n<p>アイコンを公開する前に、明るい背景と暗い背景の両方でテストしてください。白い背景に依存するアイコンは、暗いテーマでは消えてしまいます。修正方法は、透明版です。</p>\n<h2 id=\"stickers-social-graphics\">ステッカーとSNSグラフィック</h2>\n<p>ステッカーは、設計上、透明なPNGです。白い四角に囲まれたステッカーは、チャットでは壊れて見えます。透明なステッカーは、会話になじみます。</p>\n<p>文字のあるSNSグラフィックは、PNGのシャープさが必要です。PNGで保存した告知グラフィックはきれいに読めますが、JPG版は文字を柔らかくします。</p>\n<p>広く共有されるグラフィックには、両方の形式を用意してください。品質のためのPNGと、互換性のためのJPGが、すべてのプラットフォームとすべての受け取り人をカバーします。</p>\n<p>ステッカーは、少なくとも512×512ピクセルで高解像度にデザインしてください。小さいステッカーを拡大するとぼやけますが、大きいものを縮小すればシャープに残ります。</p>\n<p>ステッカーをアップロードする前に、ファイルサイズを確認してください。プラットフォームによっては、ステッカーファイルを数百KBまでに制限している場合があり、大きなPNGは先に圧縮が必要になる場合があります。</p>\n<h2 id=\"watermarks-overlays\">透かしと重ね合わせ</h2>\n<p>透かしは、写真の上に置く半透明のロゴで、機能するには部分的な透過が必要です。PNGは、透かしを透けて見せるアルファ値を保存します。JPGはできません。</p>\n<p>透かしは、被写体を隠さない隅に置いてください。顔の上の透かしは見る人を不快にしますが、静かな隅の透かしは、画像をさりげなく守ります。</p>\n<p>透かしは、30〜50%の不透明度で控えめに保ってください。かすかな透かしは、写真を損なうことなく盗難を防ぎます。濃い透かしは、画像そのものから注意をそらします。</p>\n<p>写真一式には、PNGのマスターに透かしを適用し、そのあと共有用のJPGコピーを書き出してください。PNGのマスターは透かしを編集可能に保ち、JPGは納品用の形式です。</p>\n<p>販売やライセンスする画像からは、透かしを取り除いてください。買い手はきれいなファイルを期待します。透かしは、プレビューとポートフォリオの画像だけに属します。</p>\n<h2 id=\"choosing-format-new-project\">新しいプロジェクトの形式選び</h2>\n<p>新しいプロジェクトを始めるのは、形式を意識的に選ぶ最良のタイミングです。初日からの明確なルールが、あとで形式の混ざったフォルダになるのを防ぎます。</p>\n<p>Webサイトでは、写真にWebP、ロゴにPNGを選んでください。この分け方が、速い読み込みとシャープなグラフィックをもたらし、重要な場面で透過を使えます。</p>\n<p>印刷プロジェクトでは、グラフィックにPNG、高画質の写真にJPGを選んでください。印刷所は両方を受け付け、この組み合わせはサイズとシャープさのバランスを取ります。</p>\n<p>SNSキャンペーンでは、写真にJPG、文字のあるグラフィックにPNGを選んでください。プラットフォームはどちらにせよすべてを圧縮するので、正しい形式から始めれば最良の結果になります。</p>\n<p>形式のルールを書き留め、チームと共有してください。プロジェクトメモの1行のルールが、形式が少しずつばらばらになっていくのを防ぎます。</p>\n<p>両方の間で変換が必要ですか。可逆の作業用コピーには<a href=\"/ja/jpg-png-henkan/\">JPGからPNGへの変換ツール</a>、PNGの写真を小さくするには<a href=\"/ja/png-jpg-henkan/\">PNGからJPGへの変換ツール</a>を使ってください。</p>\n<p>詳しいガイドは<a href=\"/ja/blog/jpg-png-henkan-gaido/\">JPGをPNGに変換する完全ガイド</a>と<a href=\"/ja/blog/png-jpg-henkan-gaido/\">PNGをJPGに変換する完全ガイド</a>、手順は<a href=\"/ja/blog/jpg-png-henkan-houhou/\">JPGをPNGに変換する方法</a>をご覧ください。</p>";

export const FAQS: BlogArticleFaq[] = [{"question":"JPGに透明な背景を付けられますか？","answer":"いいえ、付けられません。JPGにはアルファチャンネルがないので、すべての画素は単色で、透けて見えるJPGの画素は存在しません。透過が必要な場合は、PNGかWebPを使ってください。JPGのロゴは、常に単色の背景を持ちます。たいていは白か黒です。"},{"question":"JPGをPNGに変換すると白い背景は透明になりますか？","answer":"いいえ、なりません。白い画素は本物の画素であり、PNGはそれを白として保存します。透過は、形式を変換するのではなく、適切なツールで背景を取り除いて作らなければなりません。変換は、単色の背景を含めて、画像をそのまま保ちます。"},{"question":"WebサイトのロゴにはPNGとJPGのどちらがよいですか？","answer":"ロゴに透過が必要な場合は、PNGのほうがよいです。どの背景色の上でもロゴを置けるからです。サイトが対応している場合は、WebPがさらに優れています。透過を保ちながら、より小さいサイズに収まります。透明な背景が必要なロゴには、JPGは間違った選択です。"},{"question":"スクリーンショットがPNGのほうがJPGよりよく見えるのはなぜですか？","answer":"スクリーンショットは、シャープな文字と細い線だらけで、JPGの圧縮がそれらをにじませます。PNGはすべての画素を正確に保存するので、文字はくっきり残ります。PNGファイルは大きいですが、スクリーンショットでは読みやすさに余分なバイトの価値があります。"},{"question":"Webサイトの画像をすべてPNGにできますか？","answer":"できますが、ページの表示は遅くなります。PNGの写真は、目に見える利点がないのに、JPGの写真の数倍大きくなります。PNGはロゴ、アイコン、スクリーンショットだけに使い、写真はJPGかWebPにしてください。この分け方が、ページを速く、画像をシャープに保ちます。"},{"question":"印刷用の透明ロゴは、どの形式で保存すべきですか？","answer":"透過付きのPNGが、印刷するロゴの標準です。輪郭をシャープに保ち、背景を透けて見せます。PNGは高解像度にしてください。印刷サイズで少なくとも300DPIあれば、紙の上でロゴが柔らかく見えません。"}];
